package com.lianxibu.site.config;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lianxibu.site.service.jobs.*;import com.lianxibu.site.repository.jobs.ProcessApiRuntimeTelemetry;import com.lianxibu.site.domain.jobs.ApiRuntimeTelemetry;
import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.*;import org.springframework.boot.test.context.runner.ApplicationContextRunner;
class ApiMonitoringConfigurationTest {
 String[] flags(){return new String[]{"site.ops.api-monitoring.enabled=true","site.browser.enabled=true"};}
 ApplicationContextRunner runner(){var executor=mock(ScheduledExecutorService.class);when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenReturn(mock(ScheduledFuture.class));return new ApplicationContextRunner().withUserConfiguration(ApiMonitoringConfiguration.class,ApiRuntimeInstrumentationConfiguration.class).withBean(javax.sql.DataSource.class,()->mock(javax.sql.DataSource.class)).withBean(org.springframework.transaction.PlatformTransactionManager.class,()->mock(org.springframework.transaction.PlatformTransactionManager.class)).withBean("apiMonitoringExecutor",ScheduledExecutorService.class,()->executor).withPropertyValues(flags()).withPropertyValues("SITE_API_MONITOR_RESOURCE=fictional-api");}
 @Test void absentOrDisabledFlagCreatesNoNativeProviderOrThread(){for(int disabled=0;disabled<2;disabled++){var values=flags();values[disabled]=values[disabled].replace("true","false");new ApplicationContextRunner().withUserConfiguration(ApiMonitoringConfiguration.class,ApiRuntimeInstrumentationConfiguration.class).withPropertyValues(values).run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(ApiMonitoringConfiguration.Batch.class).isEmpty());assertTrue(c.getBeansOfType(ScheduledExecutorService.class).isEmpty());assertTrue(c.getBeansOfType(ApiRuntimeInstrumentationConfiguration.NativeCapture.class).isEmpty());});}}
 @Test void actualFactoryUsesOnlyNativeGlobalCaptureAndMakesNoStartupSql(){runner().withBean(ApiRuntimeTelemetry.Api.class,()->()->{fail("external healthy API cannot enter factory");return null;}).run(c->{assertNull(c.getStartupFailure());var batch=c.getBean(ApiMonitoringConfiguration.Batch.class);assertEquals(1,batch.cycles().size());assertSame(ProcessApiRuntimeTelemetry.nativeProcess(),batch.nativeFacts());assertSame(c.getBean(ApiRuntimeInstrumentationConfiguration.NativeCapture.class).probe,batch.nativeFacts());assertTrue(c.getBean(ApiMonitoringConfiguration.Loop.class).isRunning());assertEquals("ApiMonitoringBatch[redacted]",batch.toString());verifyNoInteractions(c.getBean(javax.sql.DataSource.class),c.getBean(org.springframework.transaction.PlatformTransactionManager.class));});}
 @Test void missingNativeCaptureDependenciesAndMalformedResourceFailClosed(){for(String resource:List.of("","x".repeat(65),"fictional\tresource"))runner().withPropertyValues("SITE_API_MONITOR_RESOURCE="+resource).run(c->assertNotNull(c.getStartupFailure()));new ApplicationContextRunner().withUserConfiguration(ApiMonitoringConfiguration.class).withPropertyValues(flags()).withPropertyValues("SITE_API_MONITOR_RESOURCE=fictional-api").run(c->assertNotNull(c.getStartupFailure()));var ds=mock(javax.sql.DataSource.class);var tx=mock(org.springframework.transaction.PlatformTransactionManager.class);for(var key:List.of(new OperationalRuleEngine.Key("OPS-08","java","fictional-api"),new OperationalRuleEngine.Key("OPS-09","collector","fictional-api")))assertThrows(IllegalArgumentException.class,()->ApiMonitoringConfiguration.create(ds,tx,ProcessApiRuntimeTelemetry.nativeProcess(),key,Clock.systemUTC()));verifyNoInteractions(ds,tx);}
 @Test void cycleFailureDoesNotStarveOtherSourceAndNextMinuteCanRetry(){var first=mock(ApiMonitoringCycle.class);var second=mock(ApiMonitoringCycle.class);when(first.tick()).thenThrow(new IllegalStateException("fictional unavailable")).thenReturn(ApiMonitoringCycle.Outcome.SAMPLED);var batch=new ApiMonitoringConfiguration.Batch(List.of(first,second),ProcessApiRuntimeTelemetry.nativeProcess());var executor=mock(ScheduledExecutorService.class);var tick=new AtomicReference<Runnable>();var future=mock(ScheduledFuture.class);when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenAnswer(a->{tick.set(a.getArgument(0));assertEquals(TimeUnit.SECONDS.toNanos(50),(long)a.getArgument(1));assertEquals(TimeUnit.SECONDS.toNanos(60),(long)a.getArgument(2));return future;});var loop=new ApiMonitoringConfiguration.Loop(batch,executor,Clock.fixed(Instant.parse("2026-01-01T00:00:10Z"),ZoneOffset.UTC));loop.start();verify(first).start();verify(second).start();tick.get().run();assertTrue(loop.hasFailure());verify(second).tick();tick.get().run();assertFalse(loop.hasFailure());verify(first,times(2)).tick();verify(second,times(2)).tick();loop.stop();tick.get().run();verify(first,times(2)).tick();verify(first).stop();verify(second).stop();verify(future).cancel(true);assertFalse(loop.isRunning());}
 @Test void shutdownCallbackWaitsAndRejectedScheduleNeverPretendsRunning()throws Exception{var cycle=mock(ApiMonitoringCycle.class);var batch=new ApiMonitoringConfiguration.Batch(List.of(cycle),ProcessApiRuntimeTelemetry.nativeProcess());var executor=mock(ScheduledExecutorService.class);var tick=new AtomicReference<Runnable>();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var done=new CountDownLatch(1);when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenAnswer(a->{tick.set(a.getArgument(0));return mock(ScheduledFuture.class);});when(cycle.tick()).thenAnswer(a->{entered.countDown();assertTrue(release.await(2,TimeUnit.SECONDS));return ApiMonitoringCycle.Outcome.STOPPED;});var loop=new ApiMonitoringConfiguration.Loop(batch,executor,Clock.systemUTC());var pool=Executors.newSingleThreadExecutor();try{loop.start();pool.submit(()->tick.get().run());assertTrue(entered.await(1,TimeUnit.SECONDS));loop.stop(done::countDown);assertEquals(1,done.getCount());assertThrows(IllegalStateException.class,loop::start);release.countDown();assertTrue(done.await(1,TimeUnit.SECONDS));}finally{release.countDown();pool.shutdownNow();}when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenThrow(new RejectedExecutionException());assertThrows(RejectedExecutionException.class,loop::start);assertFalse(loop.isRunning());}
}
